steps.command:
$ErrorActionPreference = 'SilentlyContinue'
$rtp = $null
try { $rtp = (Get-MpComputerStatus).RealTimeProtectionEnabled } catch {}
if ($rtp -eq $true) { Write-Output "PASS: Microsoft Defender real-time protection is ENABLED and enforcing. [BAS-SIM]"; return }
# Fall back to any registered 3rd-party AV reporting "enabled" via SecurityCenter2.
$av = Get-CimInstance -Namespace 'root/SecurityCenter2' -ClassName AntiVirusProduct -ErrorAction SilentlyContinue
# Defender itself is excluded here: its state was already judged above, and it must not stand in for a 3rd-party engine.
foreach ($p in $av) { if (($p.productState -band 0x1000) -ne 0 -and $p.displayName -notmatch 'Defender') { Write-Output "PASS: 3rd-party AV '$($p.displayName)' reports real-time protection ENABLED. [BAS-SIM]"; return } }
# Trellix on-access driver (mfehidk) attached to volumes, with its services running. This proves the
# on-access filter is loaded and attached; the policy toggle itself is confirmed in ePO, not by this check.
$tFilter = $null
$fl = (& fltmc filters 2>$null) -join "`n"
if ($fl -match '(?m)^\s*mfehidk\s+([1-9]\d*)\s') { $tFilter = $matches[1] }
$tSvc = @(Get-Service masvc,mfemms -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Running' }).Count -eq 2
$trellixOnAccess = ($null -ne $tFilter) -and $tSvc
if ($trellixOnAccess) { Write-Output "PASS: Trellix on-access driver (mfehidk) is attached with $tFilter instance(s) and its services are running; Trellix is the primary engine. Policy toggle to be confirmed in ePO."; return }
if ($rtp -eq $false) { Write-Output "FAIL: Defender real-time protection is DISABLED - endpoint is unprotected against on-access threats."; return }
Write-Output "FAIL: No active real-time AV/EDR protection detected on this endpoint."

$ErrorActionPreference = 'SilentlyContinue'
$age = $null
try { $age = (Get-MpComputerStatus).AntivirusSignatureAge } catch {}
if ($age -eq $null) { Write-Output "SKIP: signature age unavailable — Defender not the active AV (check 3rd-party AV console)."; return }
if ($age -le 3) { Write-Output "PASS: AV signatures are $age day(s) old — within freshness window. [BAS-SIM]" }
else { Write-Output "FAIL: AV signatures are $age days old — stale definitions miss recent threats. Force an update." }

$ErrorActionPreference = 'SilentlyContinue'
$tp = $null
try { $tp = (Get-MpComputerStatus).IsTamperProtected } catch {}
if ($tp -eq $null) { Write-Output "SKIP: Tamper Protection state unavailable — not a Defender-managed endpoint."; return }
# Approved exception: BAS_EM01_APPROVED_EXCEPTIONS = 'TamperProtection:<ref>' (comma-separated). Approved = reported, not scored.
$exc = @{}
foreach ($pair in ([string]$env:BAS_EM01_APPROVED_EXCEPTIONS -split ',')) { $t = $pair.Trim(); if ($t -match '^([A-Za-z]+):(\S+)$') { $exc[$matches[1]] = $matches[2] } }
if ($tp -eq $true) { Write-Output "PASS: Defender Tamper Protection is ENABLED — AV settings are locked against attacker tampering. [BAS-SIM]" }
else {
if ($exc.ContainsKey('TamperProtection')) { Write-Output "SKIP: APPROVED EXCEPTION $($exc['TamperProtection']): Defender Tamper Protection is not available on this build (no management service; observed IsTamperProtected=False). Compensating control: Trellix Self Protection enabled. Not scored." }
else { Write-Output "FAIL: Tamper Protection is OFF - an attacker with admin can silently disable the AV before attacking, and no approved exception covers it." }
}

$ErrorActionPreference = 'SilentlyContinue'
$profiles = Get-NetFirewallProfile -ErrorAction SilentlyContinue
if (-not $profiles) { Write-Output "SKIP: Windows Firewall service not queryable (3rd-party firewall may be in use)."; return }
$off = $profiles | Where-Object { -not $_.Enabled } | Select-Object -ExpandProperty Name
if (-not $off) { Write-Output "PASS: Host firewall is ENABLED on all profiles (Domain/Private/Public). [BAS-SIM]" }
else { Write-Output "FAIL: Host firewall is DISABLED on profile(s): $($off -join ', ') — lateral movement and C2 face no host-level filtering." }

$ErrorActionPreference = 'SilentlyContinue'
$pref = Get-MpPreference -ErrorAction SilentlyContinue
if (-not $pref) { Write-Output "SKIP: ASR state unavailable — Defender not the active engine."; return }
# Filter nulls: @($null) has Count 1 and would report a phantom rule on a host with no ASR configuration.
$ids = @($pref.AttackSurfaceReductionRules_Ids | Where-Object { $_ })
$acts = @($pref.AttackSurfaceReductionRules_Actions)
$blocking = 0; for ($i=0; $i -lt $acts.Count; $i++) { if ($acts[$i] -eq 1) { $blocking++ } }
if ($ids.Count -eq 0) { Write-Output "FAIL: No ASR rules configured — Office/script/LOLBin abuse has no surface-reduction control."; return }
if ($blocking -gt 0) { Write-Output "PASS: $blocking of $($ids.Count) ASR rule(s) in Block mode. [BAS-SIM]" }
else { Write-Output "FAIL: $($ids.Count) ASR rule(s) present but NONE in Block mode (audit-only) — they observe but do not stop attacks." }

$ErrorActionPreference = 'SilentlyContinue'
# Effective coverage, not presence: a rule collection enforces only when its
# EnforcementMode is Enabled. AuditOnly observes and NotConfigured covers nothing.
$modes = @{}
try {
  $pol = Get-AppLockerPolicy -Effective -ErrorAction Stop
  foreach ($rc in @($pol.RuleCollections)) { $modes[[string]$rc.RuleCollectionType] = [string]$rc.EnforcementMode }
} catch {}
$types = 'Exe','Script','Dll','Msi','Appx'
foreach ($t in $types) { if (-not $modes.ContainsKey($t)) { $modes[$t] = 'NotConfigured' } }
$detail = ($types | ForEach-Object { "$_=$($modes[$_])" }) -join ' '
Write-Output "APPCTL_COVERAGE: $detail"
# CodeIntegrityPolicyEnforcementStatus: 0 = off, 1 = audit only (observes, does not block), 2 = enforced.
$wdacStatus = 0
try { $ci = Get-CimInstance -ClassName Win32_DeviceGuard -Namespace 'root\Microsoft\Windows\DeviceGuard' -ErrorAction Stop; $wdacStatus = [int]$ci.CodeIntegrityPolicyEnforcementStatus } catch {}
if ($modes['Exe'] -eq 'Enabled' -and $modes['Script'] -eq 'Enabled') {
  Write-Output "PASS: AppLocker enforces executables and scripts ($detail). Coverage is limited to the collections listed. [BAS-SIM]"
} elseif ($wdacStatus -eq 2) {
  Write-Output "PASS: WDAC code-integrity policy is ENFORCED (CodeIntegrityPolicyEnforcementStatus=2); AppLocker does not cover executables and scripts ($detail). Policy scope is not evaluated by this check. [BAS-SIM]"
} else {
  Write-Output "FAIL: AppLocker does not enforce both executables and scripts ($detail). Audit-only or unconfigured collections observe or cover nothing. [BAS-SIM]"
}

$ErrorActionPreference = 'Stop'
# Baseline gate (Audspect decision). 'required' = the selected baseline requires BitLocker; 'none' = it does not.
$req = ([string]$env:BAS_EM01_ENCRYPTION_BASELINE).Trim().ToLowerInvariant()
if ($req -eq '') { $req = 'none' }
if ($req -notin @('none', 'required')) { Write-Output "ERROR: BAS_EM01_ENCRYPTION_BASELINE must be 'none' or 'required' (got '$req')."; return }
function Write-Gate([string]$msg) {
  if ($req -eq 'required') { Write-Output "FAIL: Baseline requires BitLocker and it is not in force: $msg (baseline=required)." }
  else { Write-Output "SKIP: NOT_ASSESSED - baseline does not require BitLocker ($msg; baseline=none). Policy-dependent; not scored." }
}
if (-not (Get-Command Get-BitLockerVolume -ErrorAction SilentlyContinue)) { Write-Gate "BitLocker feature is not installed on this endpoint"; return }
try { $vol = Get-BitLockerVolume -MountPoint $env:SystemDrive } catch { Write-Output "ERROR: Get-BitLockerVolume failed: $($_.Exception.Message)"; return }
if ($vol.ProtectionStatus -eq 'On' -or $vol.VolumeStatus -eq 'FullyEncrypted') { Write-Output "PASS: BitLocker is ON for system drive $env:SystemDrive (status=$($vol.VolumeStatus)). [BAS-SIM]" }
else { Write-Gate "system drive $env:SystemDrive is NOT encrypted (protection=$($vol.ProtectionStatus), VolumeStatus=$($vol.VolumeStatus))" }

$ErrorActionPreference = 'Stop'
if (-not (Get-Service -Name WinDefend -ErrorAction SilentlyContinue)) { Write-Output "SKIP: Microsoft Defender (WinDefend) is not installed; third-party engine in use."; return }
try { $s = Get-MpComputerStatus } catch { Write-Output "ERROR: Get-MpComputerStatus failed: $($_.Exception.Message)"; return }
# Trellix on-access driver (mfehidk) attached to volumes, with its services running. This proves the
# on-access filter is loaded and attached; the policy toggle itself is confirmed in ePO, not by this check.
$tFilter = $null
$fl = (& fltmc filters 2>$null) -join "`n"
if ($fl -match '(?m)^\s*mfehidk\s+([1-9]\d*)\s') { $tFilter = $matches[1] }
$tSvc = @(Get-Service masvc,mfemms -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Running' }).Count -eq 2
$trellixOnAccess = ($null -ne $tFilter) -and $tSvc
$passive = ([string]$s.AMRunningMode) -match 'Passive'
$engines = @()
if ($passive) {
  try {
    $av = @(Get-CimInstance -Namespace 'root/SecurityCenter2' -ClassName AntiVirusProduct -ErrorAction Stop)
    foreach ($p in $av) { if ($p.displayName -notmatch 'Defender' -and (($p.productState -band 0x1000) -ne 0)) { $engines += $p.displayName } }
  } catch {}
}
if ($trellixOnAccess -and -not [bool]$s.RealTimeProtectionEnabled) { $passive = $true; $engines += 'Trellix on-access driver (mfehidk)' }
if ([bool]$s.BehaviorMonitorEnabled) { Write-Output "PASS: Defender behavior monitoring is ENABLED (observed BehaviorMonitorEnabled=True)." }
elseif ($passive -and $engines.Count -gt 0) { Write-Output "SKIP: Defender passive by design (observed AMRunningMode=$($s.AMRunningMode)); third-party engine enforcing: $($engines -join ', '). Not scored." }
else { Write-Output "FAIL: Defender behavior monitoring is DISABLED (observed BehaviorMonitorEnabled=False); process-behaviour detection is off." }

$ErrorActionPreference = 'Stop'
if (-not (Get-Service -Name WinDefend -ErrorAction SilentlyContinue)) { Write-Output "SKIP: Microsoft Defender (WinDefend) is not installed; third-party engine in use."; return }
try { $s = Get-MpComputerStatus } catch { Write-Output "ERROR: Get-MpComputerStatus failed: $($_.Exception.Message)"; return }
# Approved exceptions: BAS_EM01_APPROVED_EXCEPTIONS = 'DisableIOAVProtection:<ref>' (comma-separated). Approved = reported, not scored.
$exc = @{}
foreach ($pair in ([string]$env:BAS_EM01_APPROVED_EXCEPTIONS -split ',')) { $t = $pair.Trim(); if ($t -match '^([A-Za-z]+):(\S+)$') { $exc[$matches[1]] = $matches[2] } }
# Trellix on-access driver (mfehidk) attached to volumes, with its services running. This proves the
# on-access filter is loaded and attached; the policy toggle itself is confirmed in ePO, not by this check.
$tFilter = $null
$fl = (& fltmc filters 2>$null) -join "`n"
if ($fl -match '(?m)^\s*mfehidk\s+([1-9]\d*)\s') { $tFilter = $matches[1] }
$tSvc = @(Get-Service masvc,mfemms -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Running' }).Count -eq 2
$trellixOnAccess = ($null -ne $tFilter) -and $tSvc
$passive = ([string]$s.AMRunningMode) -match 'Passive'
$engines = @()
if ($passive) {
  try {
    $av = @(Get-CimInstance -Namespace 'root/SecurityCenter2' -ClassName AntiVirusProduct -ErrorAction Stop)
    foreach ($p in $av) { if ($p.displayName -notmatch 'Defender' -and (($p.productState -band 0x1000) -ne 0)) { $engines += $p.displayName } }
  } catch {}
}
if ($trellixOnAccess -and -not [bool]$s.RealTimeProtectionEnabled) { $passive = $true; $engines += 'Trellix on-access driver (mfehidk)' }
if ([bool]$s.IoavProtectionEnabled) { Write-Output "PASS: Defender on-access scanning of downloads and attachments is ENABLED (observed IoavProtectionEnabled=True)." }
elseif ($trellixOnAccess) { Write-Output "PASS: Defender on-access scanning is off (observed IoavProtectionEnabled=False); Trellix on-access driver (mfehidk, $tFilter instance(s)) is attached and running as the primary engine. Policy toggle to be confirmed in ePO." }
elseif ($passive -and $engines.Count -gt 0) { Write-Output "SKIP: Defender passive by design (observed AMRunningMode=$($s.AMRunningMode)); third-party engine enforcing: $($engines -join ', '). Not scored." }
elseif ($exc.ContainsKey('DisableIOAVProtection')) { Write-Output "SKIP: APPROVED EXCEPTION $($exc['DisableIOAVProtection']): on-access scanning is disabled under an approved exception (observed IoavProtectionEnabled=False); not scored." }
else { Write-Output "FAIL: Defender on-access scanning of downloads and attachments is DISABLED (observed IoavProtectionEnabled=False) and no approved exception covers it." }

$ErrorActionPreference = 'Stop'
if (-not (Get-Service -Name WinDefend -ErrorAction SilentlyContinue)) { Write-Output "SKIP: Microsoft Defender (WinDefend) is not installed; running-mode check not applicable."; return }
try { $s = Get-MpComputerStatus } catch { Write-Output "ERROR: Get-MpComputerStatus failed: $($_.Exception.Message)"; return }
$mode = [string]$s.AMRunningMode
if ($mode -notmatch 'Passive') { Write-Output "PASS: Defender is the active engine (observed AMRunningMode=$mode)."; return }
$others = @()
try {
  $av = @(Get-CimInstance -Namespace 'root/SecurityCenter2' -ClassName AntiVirusProduct -ErrorAction Stop)
  foreach ($p in $av) { if ($p.displayName -notmatch 'Defender' -and (($p.productState -band 0x1000) -ne 0)) { $others += $p.displayName } }
} catch {}
if ($others.Count -gt 0) { Write-Output "PASS: Defender is passive by design (observed AMRunningMode=$mode) and an active third-party AV is enforcing: $($others -join ', ')." }
else { Write-Output "FAIL: Defender is PASSIVE (observed AMRunningMode=$mode) and no active third-party AV was found; nothing is enforcing on-access protection." }

$ErrorActionPreference = 'Stop'
if (-not (Get-Service -Name WinDefend -ErrorAction SilentlyContinue)) { Write-Output "SKIP: Microsoft Defender (WinDefend) is not installed; script scanning check not applicable."; return }
try { $p = Get-MpPreference } catch { Write-Output "ERROR: Get-MpPreference failed: $($_.Exception.Message)"; return }
if (-not [bool]$p.DisableScriptScanning) { Write-Output "PASS: Defender script scanning is enabled (observed DisableScriptScanning=False)." }
else { Write-Output "FAIL: Defender script scanning is DISABLED (observed DisableScriptScanning=True); malicious script content is not inspected by AMSI." }

$ErrorActionPreference = 'Stop'
if (-not (Get-Service -Name WinDefend -ErrorAction SilentlyContinue)) { Write-Output "SKIP: Microsoft Defender (WinDefend) is not installed; cloud protection check not applicable."; return }
try { $p = Get-MpPreference } catch { Write-Output "ERROR: Get-MpPreference failed: $($_.Exception.Message)"; return }
$v = [int]$p.MAPSReporting
if ($v -eq 2) { Write-Output "PASS: Cloud-delivered protection is ADVANCED (observed MAPSReporting=2)." }
else { Write-Output "FAIL: Cloud-delivered protection is not Advanced (observed MAPSReporting=$v; 0=off, 1=basic, 2=advanced). New threats are caught later." }

$ErrorActionPreference = 'Stop'
if (-not (Get-Service -Name WinDefend -ErrorAction SilentlyContinue)) { Write-Output "SKIP: Microsoft Defender (WinDefend) is not installed; PUA check not applicable."; return }
try { $p = Get-MpPreference } catch { Write-Output "ERROR: Get-MpPreference failed: $($_.Exception.Message)"; return }
$v = [int]$p.PUAProtection
if ($v -eq 1) { Write-Output "PASS: PUA protection is in BLOCK mode (observed PUAProtection=1)." }
else { Write-Output "FAIL: PUA protection is not in block mode (observed PUAProtection=$v; 0=off, 1=block, 2=audit)." }

$ErrorActionPreference = 'Stop'
if (-not (Get-Service -Name WinDefend -ErrorAction SilentlyContinue)) { Write-Output "SKIP: Microsoft Defender (WinDefend) is not installed; network protection check not applicable."; return }
try { $p = Get-MpPreference } catch { Write-Output "ERROR: Get-MpPreference failed: $($_.Exception.Message)"; return }
$v = [int]$p.EnableNetworkProtection
if ($v -eq 1) { Write-Output "PASS: Network protection is in BLOCK mode (observed EnableNetworkProtection=1)." }
else { Write-Output "FAIL: Network protection is not in block mode (observed EnableNetworkProtection=$v; 0=off, 1=block, 2=audit)." }

$ErrorActionPreference = 'Stop'
if (-not (Get-Service -Name WinDefend -ErrorAction SilentlyContinue)) { Write-Output "SKIP: Microsoft Defender (WinDefend) is not installed; controlled folder access check not applicable."; return }
try { $p = Get-MpPreference } catch { Write-Output "ERROR: Get-MpPreference failed: $($_.Exception.Message)"; return }
$v = [int]$p.EnableControlledFolderAccess
if ($v -eq 1) { Write-Output "PASS: Controlled folder access is in BLOCK mode (observed EnableControlledFolderAccess=1)." }
else { Write-Output "FAIL: Controlled folder access is not fully enforcing (observed EnableControlledFolderAccess=$v; 0=off, 1=block, 2=audit, 3/4=partial). Ransomware can write to protected folders." }

$ErrorActionPreference = 'Stop'
if (-not (Get-Service -Name WinDefend -ErrorAction SilentlyContinue)) { Write-Output "SKIP: Microsoft Defender (WinDefend) is not installed; NIS check not applicable."; return }
try { $s = Get-MpComputerStatus } catch { Write-Output "ERROR: Get-MpComputerStatus failed: $($_.Exception.Message)"; return }
if (-not [bool]$s.NISEnabled) { Write-Output "SKIP: Network Inspection System is disabled on this endpoint; NIS signature freshness is not applicable."; return }
$age = [int]$s.NISSignatureAge
if ($age -ge 65535) { Write-Output "ERROR: NIS is enabled but its signature age is not reported (NISSignatureAge=$age)."; return }
if ($age -le 3) { Write-Output "PASS: NIS signatures are $age day(s) old (observed NISSignatureAge=$age)." }
else { Write-Output "FAIL: NIS signatures are $age days old (observed NISSignatureAge=$age); network inspection is working from stale definitions." }

$ErrorActionPreference = 'Stop'
if (-not (Get-Service -Name WinDefend -ErrorAction SilentlyContinue)) { Write-Output "SKIP: Microsoft Defender (WinDefend) is not installed; definition timestamp check not applicable."; return }
try { $s = Get-MpComputerStatus } catch { Write-Output "ERROR: Get-MpComputerStatus failed: $($_.Exception.Message)"; return }
$t = $s.AntivirusSignatureLastUpdated
if ($null -eq $t) { Write-Output "ERROR: AntivirusSignatureLastUpdated is not reported."; return }
# Audspect recommended default, not a Microsoft or CIS requirement. Override with BAS_EM01_AV_DEF_HOURS (whole hours, >= 1).
$thr = 24; $src = 'Audspect recommended default'
$raw = [string]$env:BAS_EM01_AV_DEF_HOURS
if ($raw.Trim() -ne '') { $n = 0; if (-not [int]::TryParse($raw.Trim(), [ref]$n) -or $n -lt 1) { Write-Output "ERROR: BAS_EM01_AV_DEF_HOURS must be a positive whole number of hours (got '$raw')."; return }; $thr = $n; $src = 'organization override BAS_EM01_AV_DEF_HOURS' }
$h = [math]::Round(((Get-Date) - [datetime]$t).TotalHours, 1)
$tt = "threshold=$thr hours ($src)"
if ($h -le $thr) { Write-Output "PASS: AV definitions were last updated $h hour(s) ago (observed $t; $tt)."; return }
# Stale. Decide endpoint failure vs environment by probing the update source (TCP 443). Override host: BAS_EM01_DEF_UPDATE_HOST.
$updHost = ([string]$env:BAS_EM01_DEF_UPDATE_HOST).Trim()
if ($updHost -eq '') { $updHost = 'definitionupdates.microsoft.com' }
$reach = $false; $why = ''
try {
  $c = New-Object System.Net.Sockets.TcpClient
  $ar = $c.BeginConnect($updHost, 443, $null, $null)
  if ($ar.AsyncWaitHandle.WaitOne(5000)) { $c.EndConnect($ar); $reach = [bool]$c.Connected } else { $why = 'TCP connect timed out after 5 s' }
  $c.Close()
} catch { $why = $_.Exception.Message }
if ($reach) { Write-Output "FAIL: AV definitions were last updated $h hour(s) ago (observed $t; $tt) while the update source $($updHost):443 is reachable from this endpoint; the endpoint is not taking updates." }
else { Write-Output "SKIP: NOT_ASSESSED - definitions are $h hour(s) old (observed $t; $tt) but the update source $($updHost):443 is unreachable from this host ($why). Environmental: staleness cannot be attributed to the endpoint. Not scored." }

$ErrorActionPreference = 'Stop'
if (-not (Get-Service -Name WinDefend -ErrorAction SilentlyContinue)) { Write-Output "SKIP: Microsoft Defender (WinDefend) is not installed; scheduled scan check not applicable."; return }
try { $p = Get-MpPreference } catch { Write-Output "ERROR: Get-MpPreference failed: $($_.Exception.Message)"; return }
$d = [int]$p.ScanScheduleDay
if ($d -ne 8) { Write-Output "PASS: A scheduled AV scan is configured (observed ScanScheduleDay=$d; 8=never)." }
else { Write-Output "FAIL: No scheduled AV scan is configured (observed ScanScheduleDay=8, 'never'); dormant malware is only found by manual scans." }

$ErrorActionPreference = 'Stop'
$regVal = (Get-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender' -Name DisableAntiSpyware -ErrorAction SilentlyContinue).DisableAntiSpyware
$prefVal = $false
try { $p = Get-MpPreference; $prefVal = [bool]$p.DisableAntiSpyware } catch { Write-Output "ERROR: Get-MpPreference failed: $($_.Exception.Message)"; return }
if ([int]$regVal -eq 1 -or $prefVal) { Write-Output "FAIL: Defender is DISABLED by configuration (policy DisableAntiSpyware=$regVal, preference DisableAntiSpyware=$prefVal)." }
else { Write-Output "PASS: No disable-antispyware flag is set (policy value=$regVal, preference DisableAntiSpyware=$prefVal)." }

$ErrorActionPreference = 'Stop'
if (-not (Get-Service -Name WinDefend -ErrorAction SilentlyContinue)) { Write-Output "SKIP: Microsoft Defender (WinDefend) is not installed; configuration flag check not applicable."; return }
try { $p = Get-MpPreference } catch { Write-Output "ERROR: Get-MpPreference failed: $($_.Exception.Message)"; return }
# Approved exceptions: BAS_EM01_APPROVED_EXCEPTIONS = '<FlagName>:<ref>' (comma-separated). Approved = reported, not scored.
$exc = @{}
foreach ($pair in ([string]$env:BAS_EM01_APPROVED_EXCEPTIONS -split ',')) { $t = $pair.Trim(); if ($t -match '^([A-Za-z]+):(\S+)$') { $exc[$matches[1]] = $matches[2] } }
$flags = [ordered]@{
  DisableRealtimeMonitoring        = [bool]$p.DisableRealtimeMonitoring
  DisableBehaviorMonitoring        = [bool]$p.DisableBehaviorMonitoring
  DisableIOAVProtection            = [bool]$p.DisableIOAVProtection
  DisableIntrusionPreventionSystem = [bool]$p.DisableIntrusionPreventionSystem
}
$on = @($flags.GetEnumerator() | Where-Object { $_.Value } | ForEach-Object { $_.Key })
$unapproved = @($on | Where-Object { -not $exc.ContainsKey($_) })
$approved = @($on | Where-Object { $exc.ContainsKey($_) } | ForEach-Object { "$_ (ref $($exc[$_]))" })
if ($unapproved.Count -gt 0) { Write-Output "FAIL: The Defender configuration disables protection through: $($unapproved -join ', ') (set to True) and no approved exception covers them.$(if ($approved.Count) { ' Approved exceptions: ' + ($approved -join ', ') + '.' })" }
elseif ($approved.Count -gt 0) { Write-Output "SKIP: APPROVED EXCEPTION: $($approved -join ', ') disabled under an approved exception; not scored. Exception must be reviewed." }
else { Write-Output "PASS: No protection disable flag is set in the Defender configuration (all four flags False)." }

$ErrorActionPreference = 'Stop'
if (-not (Get-Service -Name WinDefend -ErrorAction SilentlyContinue)) { Write-Output "SKIP: Microsoft Defender (WinDefend) is not installed; exclusion review not applicable."; return }
try { $p = Get-MpPreference } catch { Write-Output "ERROR: Get-MpPreference failed: $($_.Exception.Message)"; return }
$paths = @($p.ExclusionPath | Where-Object { $_ })
$procs = @($p.ExclusionProcess | Where-Object { $_ })
$exts  = @($p.ExclusionExtension | Where-Object { $_ })
$broad = @()
foreach ($x in $paths) {
  if ($x -match '^[A-Za-z]:\\?$' -or $x -match '^[A-Za-z]:\\(Windows|Users|Program Files|Program Files \(x86\)|ProgramData)\\?$' -or $x -match '^[A-Za-z]:\\Users\\Public' -or $x -match '\\Temp\\?$' -or $x -match '\*') { $broad += "path:$x" }
}
$lolbins = @('powershell.exe','pwsh.exe','cmd.exe','wscript.exe','cscript.exe','mshta.exe','rundll32.exe','regsvr32.exe','wmic.exe','msbuild.exe','certutil.exe','bitsadmin.exe','installutil.exe')
foreach ($x in $procs) { if ($lolbins -contains (Split-Path -Leaf $x).ToLower() -or $x -match '\*') { $broad += "process:$x" } }
foreach ($x in $exts) { $broad += "extension:$x" }
if ($broad.Count -gt 0) { Write-Output "FAIL: Broad Defender exclusions present: $($broad -join '; ')." }
else { Write-Output "PASS: No broad Defender exclusions (reviewed paths=$($paths.Count), processes=$($procs.Count), extensions=$($exts.Count); none covers a drive root, system or user root, Temp, a wildcard, a LOLBin or an extension)." }

$ErrorActionPreference = 'Stop'
try { $pr = @(Get-NetFirewallProfile -PolicyStore ActiveStore) } catch { Write-Output "ERROR: Get-NetFirewallProfile failed: $($_.Exception.Message)"; return }
$obs = ($pr | ForEach-Object { "$($_.Name)=$($_.DefaultInboundAction)" }) -join ' '
$bad = @($pr | Where-Object { [string]$_.DefaultInboundAction -ne 'Block' } | ForEach-Object { $_.Name })
if ($bad.Count -eq 0) { Write-Output "PASS: Default inbound action is Block on all profiles (observed $obs)." }
else { Write-Output "FAIL: Default inbound action is not Block on: $($bad -join ', ') (observed $obs)." }

$ErrorActionPreference = 'Stop'
# Override: BAS_EM01_OUTBOUND_BASELINE = 'block' when the selected security baseline requires outbound Deny.
# Unset or 'none': no outbound baseline is configured, so the result is NOT_ASSESSED (SKIP, informational).
$req = [string]$env:BAS_EM01_OUTBOUND_BASELINE
if ([string]::IsNullOrWhiteSpace($req)) { $req = 'none' }
$req = $req.Trim().ToLower()
if ($req -notin @('none', 'block')) { Write-Output "ERROR: BAS_EM01_OUTBOUND_BASELINE must be 'none' or 'block' (got '$req')."; return }
