try { $vol = Get-BitLockerVolume -MountPoint $env:SystemDrive } catch { Write-Output "ERROR: Get-BitLockerVolume failed: $($_.Exception.Message)"; return }
try { $all = @(Get-BitLockerVolume) } catch { Write-Output "ERROR: Get-BitLockerVolume failed: $($_.Exception.Message)"; return }
$data = @($all | Where-Object { [string]$_.VolumeType -eq 'FixedData' })
if ($data.Count -eq 0) { Write-Output "PASS: No fixed data volumes are present; only the system volume holds data-at-rest on this endpoint."; return }
$bad = @($data | Where-Object { [string]$_.VolumeStatus -ne 'FullyEncrypted' } | ForEach-Object { "$($_.MountPoint)=$($_.VolumeStatus)" })
if ($bad.Count -eq 0) { Write-Output "PASS: All $($data.Count) fixed data volume(s) are FullyEncrypted." }
else { Write-Gate "fixed data volume(s) not fully encrypted: $($bad -join ', ')" }

$ErrorActionPreference = 'Stop'
# TPM is a BitLocker prerequisite, so it follows the same baseline gate (BAS_EM01_ENCRYPTION_BASELINE).
$req = ([string]$env:BAS_EM01_ENCRYPTION_BASELINE).Trim().ToLowerInvariant()
if ($req -eq '') { $req = 'none' }
if ($req -notin @('none', 'required')) { Write-Output "ERROR: BAS_EM01_ENCRYPTION_BASELINE must be 'none' or 'required' (got '$req')."; return }
function Write-Gate([string]$msg) {
  if ($req -eq 'required') { Write-Output "FAIL: Baseline requires a TPM and it is not in force: $msg (baseline=required)." }
  else { Write-Output "SKIP: NOT_ASSESSED - baseline does not require a TPM ($msg; baseline=none). Policy-dependent; not scored." }
}
if (-not (Get-Command Get-Tpm -ErrorAction SilentlyContinue)) { Write-Gate "Get-Tpm is not available on this endpoint"; return }
try { $t = Get-Tpm } catch { Write-Output "ERROR: Get-Tpm failed: $($_.Exception.Message)"; return }
if ([bool]$t.TpmPresent -and [bool]$t.TpmReady) { Write-Output "PASS: TPM is present and ready (TpmPresent=True, TpmReady=True)." }
else { Write-Gate "TPM is not present or not ready (TpmPresent=$($t.TpmPresent), TpmReady=$($t.TpmReady)); BitLocker cannot bind keys to hardware" }

$ErrorActionPreference = 'Stop'
$svc = Get-Service -Name wscsvc -ErrorAction SilentlyContinue
if (-not $svc) { Write-Output "SKIP: Windows Security Center service is not present on this SKU."; return }
if ([string]$svc.Status -eq 'Running') { Write-Output "PASS: Windows Security Center service is Running (StartType=$($svc.StartType))." }
else { Write-Output "FAIL: Windows Security Center service is $($svc.Status); AV health is not reported to the console." }

$ErrorActionPreference = 'Stop'
try { $av = @(Get-CimInstance -Namespace 'root/SecurityCenter2' -ClassName AntiVirusProduct -ErrorAction Stop) } catch { Write-Output "SKIP: SecurityCenter2 AntiVirusProduct is not available on this SKU or configuration ($($_.Exception.Message))."; return }
if ($av.Count -eq 0) { Write-Output "FAIL: Security Center registers no antivirus product."; return }
$en = @($av | Where-Object { ($_.productState -band 0x1000) -ne 0 } | ForEach-Object { $_.displayName })
if ($en.Count -gt 0) { Write-Output "PASS: Security Center reports an enabled AV provider: $($en -join ', ')." }
else { Write-Output "FAIL: Security Center registers AV product(s) but none report enabled: $((@($av | ForEach-Object { $_.displayName })) -join ', ')." }

$ErrorActionPreference = 'Stop'
try { $av = @(Get-CimInstance -Namespace 'root/SecurityCenter2' -ClassName AntiVirusProduct -ErrorAction Stop) } catch { Write-Output "SKIP: SecurityCenter2 AntiVirusProduct is not available on this SKU or configuration ($($_.Exception.Message))."; return }
$enabled = @($av | Where-Object { ($_.productState -band 0x1000) -ne 0 })
if ($enabled.Count -eq 0) { Write-Output "SKIP: No enabled AV provider is registered; definition state not applicable."; return }
$stale = @($enabled | Where-Object { ($_.productState -band 0x0010) -ne 0 } | ForEach-Object { $_.displayName })
if ($stale.Count -eq 0) { Write-Output "PASS: Security Center reports definitions up to date for: $(@($enabled | ForEach-Object { $_.displayName }) -join ', ')." }
else { Write-Output "FAIL: Security Center reports out-of-date definitions for: $($stale -join ', ')." }

$ErrorActionPreference = 'Stop'
$svc = Get-Service -Name WinDefend -ErrorAction SilentlyContinue
if (-not $svc) { Write-Output "SKIP: Microsoft Defender Antivirus service is not installed; third-party engine in use."; return }
if ([string]$svc.Status -eq 'Running') { Write-Output "PASS: WinDefend is Running (StartType=$($svc.StartType))." }
else { Write-Output "FAIL: WinDefend is $($svc.Status) (StartType=$($svc.StartType)); the AV engine is not protecting this endpoint." }

$ErrorActionPreference = 'Stop'
$svc = Get-Service -Name Sense -ErrorAction SilentlyContinue
if (-not $svc) { Write-Output "SKIP: MDE sensor (Sense) is not installed; the endpoint is not onboarded to Defender for Endpoint on this host (verify in the EDR console)."; return }
if ([string]$svc.Status -eq 'Running') { Write-Output "PASS: MDE sensor (Sense) is Running (StartType=$($svc.StartType))."; return }
# Sense ships with Windows but is only expected to run once the endpoint is onboarded. Presence alone is not an expectation.
$ob = (Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows Advanced Threat Protection' -Name OnboardingState -ErrorAction SilentlyContinue).OnboardingState
$onboarded = ($null -ne $ob -and [int]$ob -eq 1)
$expected = $onboarded -or ([string]$svc.StartType -eq 'Automatic')
if (-not $expected) { $shown = 'absent'; if ($null -ne $ob) { $shown = $ob }; Write-Output "SKIP: MDE sensor (Sense) is present but not onboarded (OnboardingState=$shown, StartType=$($svc.StartType)); no EDR telemetry is expected here. Verify onboarding in the EDR console."; return }
Write-Output "FAIL: MDE sensor (Sense) is $($svc.Status) although the endpoint is onboarded or set to start automatically (StartType=$($svc.StartType), OnboardingState=$ob); EDR telemetry is not being produced."

$ErrorActionPreference = 'Stop'
if (-not (Get-Service -Name WinDefend -ErrorAction SilentlyContinue)) { Write-Output "SKIP: Microsoft Defender is not installed; NIS service check not applicable."; return }
try { $s = Get-MpComputerStatus } catch { Write-Output "ERROR: Get-MpComputerStatus failed: $($_.Exception.Message)"; return }
if (-not [bool]$s.NISEnabled) { Write-Output "SKIP: Network Inspection System is disabled on this endpoint; WdNisSvc is not required."; return }
$svc = Get-Service -Name WdNisSvc -ErrorAction SilentlyContinue
if (-not $svc) { Write-Output "FAIL: NIS is enabled but the WdNisSvc service is missing."; return }
if ([string]$svc.Status -eq 'Running') { Write-Output "PASS: WdNisSvc is Running while NIS is enabled." }
else { Write-Output "FAIL: NIS is enabled but WdNisSvc is $($svc.Status); network inspection is not running." }

$ErrorActionPreference = 'Stop'
$svc = Get-Service -Name EventLog -ErrorAction SilentlyContinue
if (-not $svc) { Write-Output "FAIL: Windows Event Log service (EventLog) is not present."; return }
if ([string]$svc.Status -eq 'Running') { Write-Output "PASS: Windows Event Log service is Running." }
else { Write-Output "FAIL: Windows Event Log service is $($svc.Status); no security events are recorded." }

$ErrorActionPreference = 'Stop'
$svc = Get-Service -Name Sysmon64 -ErrorAction SilentlyContinue
if (-not $svc) { $svc = Get-Service -Name Sysmon -ErrorAction SilentlyContinue }
if (-not $svc) { Write-Output "SKIP: Sysmon is not deployed on this endpoint (optional telemetry source)."; return }
if ([string]$svc.Status -eq 'Running') { Write-Output "PASS: Sysmon service ($($svc.Name)) is Running." }
else { Write-Output "FAIL: Sysmon service ($($svc.Name)) is $($svc.Status); process and network telemetry is missing." }

$ErrorActionPreference = 'Stop'
try { $l = Get-WinEvent -ListLog Security -ErrorAction Stop } catch { Write-Output "ERROR: Get-WinEvent -ListLog Security failed: $($_.Exception.Message)"; return }
$mb = [math]::Round($l.MaximumSizeInBytes / 1MB, 1)
# Audspect recommended default, not a Microsoft or CIS requirement. Override with BAS_EM01_SECLOG_MB (whole MB, >= 1).
$thr = 192; $src = 'Audspect recommended default'
$raw = [string]$env:BAS_EM01_SECLOG_MB
if ($raw.Trim() -ne '') { $n = 0; if (-not [int]::TryParse($raw.Trim(), [ref]$n) -or $n -lt 1) { Write-Output "ERROR: BAS_EM01_SECLOG_MB must be a positive whole number of MB (got '$raw')."; return }; $thr = $n; $src = 'organization override BAS_EM01_SECLOG_MB' }
$tt = "threshold=$thr MB ($src)"
if ($l.MaximumSizeInBytes -ge ($thr * 1MB)) { Write-Output "PASS: Security log maximum size is $mb MB, meets the threshold (observed $mb MB; $tt)." }
else { Write-Output "FAIL: Security log maximum size is $mb MB, below the threshold (observed $mb MB; $tt); evidence rolls over quickly under process-creation volume." }

$ErrorActionPreference = 'Stop'
$pol = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' -ErrorAction Stop
if ($null -eq $pol.EnableLUA -or $null -eq $pol.ConsentPromptBehaviorAdmin) { Write-Output "ERROR: UAC values EnableLUA or ConsentPromptBehaviorAdmin are not present; state cannot be determined."; return }
$lua = [int]$pol.EnableLUA; $cons = [int]$pol.ConsentPromptBehaviorAdmin
if ($lua -ne 1) { Write-Output "FAIL: UAC is DISABLED (observed EnableLUA=$lua); every process runs with the full token of an admin." }
elseif ($cons -eq 0) { Write-Output "FAIL: Admin elevation is silent (observed ConsentPromptBehaviorAdmin=0); elevation happens without consent." }
else { Write-Output "PASS: UAC is enabled and admin elevation prompts (observed EnableLUA=1, ConsentPromptBehaviorAdmin=$cons)." }

$ErrorActionPreference = 'Stop'
if (-not (Get-Command Get-SmbServerConfiguration -ErrorAction SilentlyContinue)) { Write-Output "SKIP: SMB server cmdlets are not available on this endpoint."; return }
try { $c = Get-SmbServerConfiguration } catch { Write-Output "ERROR: Get-SmbServerConfiguration failed: $($_.Exception.Message)"; return }
if (-not [bool]$c.EnableSMB1Protocol) { Write-Output "PASS: SMBv1 server protocol is disabled (observed EnableSMB1Protocol=False)." }
else { Write-Output "FAIL: SMBv1 server protocol is ENABLED (observed EnableSMB1Protocol=True); legacy SMB exploits are reachable." }

$ErrorActionPreference = 'Stop'
$v = (Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' -Name RunAsPPL -ErrorAction SilentlyContinue).RunAsPPL
if ($null -ne $v -and ([int]$v -eq 1 -or [int]$v -eq 2)) { Write-Output "PASS: LSA protection is enabled (observed RunAsPPL=$v)." }
else { $shown = 'absent'; if ($null -ne $v) { $shown = $v }; Write-Output "FAIL: LSA protection is not enabled (observed RunAsPPL=$shown); LSASS memory can be read by credential-dumping tools." }

$ErrorActionPreference = 'Stop'
$v = (Get-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\PowerShell\ScriptBlockLogging' -Name EnableScriptBlockLogging -ErrorAction SilentlyContinue).EnableScriptBlockLogging
if ([int]$v -eq 1) { Write-Output "PASS: PowerShell script block logging is enabled (observed EnableScriptBlockLogging=1)." }
else { $shown = 'absent'; if ($null -ne $v) { $shown = $v }; Write-Output "FAIL: PowerShell script block logging is not enabled (observed EnableScriptBlockLogging=$shown); script content is not recorded." }

$ErrorActionPreference = 'Stop'
try { $rows = @(auditpol /get /subcategory:"{0CCE922B-69AE-11D9-BED3-505054503030}" /r | Where-Object { $_ -match ',' } | ConvertFrom-Csv) } catch { Write-Output "ERROR: auditpol query failed: $($_.Exception.Message)"; return }
if ($rows.Count -eq 0) { Write-Output "ERROR: auditpol returned no Process Creation row."; return }
$set = [string]$rows[0].'Inclusion Setting'
if ($set -match 'Success') { Write-Output "PASS: Process Creation auditing includes Success (observed '$set')." }
else { Write-Output "FAIL: Process Creation auditing does not include Success (observed '$set'); Event 4688 is not written." }

$ErrorActionPreference = 'Stop'
$v = (Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System\Audit' -Name ProcessCreationIncludeCmdLine_Enabled -ErrorAction SilentlyContinue).ProcessCreationIncludeCmdLine_Enabled
if ([int]$v -eq 1) { Write-Output "PASS: Process creation events include the command line (observed ProcessCreationIncludeCmdLine_Enabled=1)." }
else { $shown = 'absent'; if ($null -ne $v) { $shown = $v }; Write-Output "FAIL: Command-line capture for process creation is not enabled (observed $shown); 4688 events lack command lines." }

$ErrorActionPreference = 'Stop'
$v = (Get-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient' -Name EnableMulticast -ErrorAction SilentlyContinue).EnableMulticast
if ($null -ne $v -and [int]$v -eq 0) { Write-Output "PASS: LLMNR is disabled by policy (observed EnableMulticast=0)." }
else { $shown = 'not set'; if ($null -ne $v) { $shown = $v }; Write-Output "FAIL: LLMNR is not disabled by policy (observed EnableMulticast=$shown); LLMNR poisoning can capture credentials." }

$ErrorActionPreference = 'Stop'
try { $sb = [bool](Confirm-SecureBootUEFI) } catch {
  if ($_.Exception.Message -match 'not supported') { Write-Output "SKIP: Secure Boot is not applicable (legacy BIOS or platform does not support the query)."; return }
  Write-Output "ERROR: Confirm-SecureBootUEFI failed: $($_.Exception.Message)"; return }
if ($sb) { Write-Output "PASS: Secure Boot is enabled (Confirm-SecureBootUEFI=True)." }
else { Write-Output "FAIL: Secure Boot is disabled (Confirm-SecureBootUEFI=False); unsigned boot components are not blocked." }

$ErrorActionPreference = 'Stop'
try { $dg = Get-CimInstance -ClassName Win32_DeviceGuard -Namespace 'root\Microsoft\Windows\DeviceGuard' -ErrorAction Stop } catch { Write-Output "ERROR: Win32_DeviceGuard query failed: $($_.Exception.Message)"; return }
if ($null -eq $dg) { Write-Output "ERROR: Win32_DeviceGuard returned no data."; return }
if (-not (@($dg.AvailableSecurityProperties) -contains 1)) { Write-Output "SKIP: Hypervisor support is not available on this hardware; VBS is not applicable."; return }
$st = [int]$dg.VirtualizationBasedSecurityStatus
if ($st -eq 2) { Write-Output "PASS: Virtualization-based security is running (observed VirtualizationBasedSecurityStatus=2)." }
else { Write-Output "FAIL: Virtualization-based security is not running (observed status=$st); credential isolation is unavailable." }

$ErrorActionPreference = 'Stop'
try { $dg = Get-CimInstance -ClassName Win32_DeviceGuard -Namespace 'root\Microsoft\Windows\DeviceGuard' -ErrorAction Stop } catch { Write-Output "ERROR: Win32_DeviceGuard query failed: $($_.Exception.Message)"; return }
if ($null -eq $dg) { Write-Output "ERROR: Win32_DeviceGuard returned no data."; return }
if (-not (@($dg.AvailableSecurityProperties) -contains 1)) { Write-Output "SKIP: Hypervisor support is not available on this hardware; memory integrity is not applicable."; return }
$run = @($dg.SecurityServicesRunning)
$sbPrereq = (@($dg.AvailableSecurityProperties) -contains 2)
if ($run -contains 2) { Write-Output "PASS: Memory integrity (HVCI) is running (SecurityServicesRunning includes 2)." }
else { Write-Output "FAIL: Memory integrity (HVCI) is not running (observed SecurityServicesRunning=$($run -join ','); prerequisite Secure Boot available=$sbPrereq); kernel code is not verified." }

$ErrorActionPreference = 'Stop'
$deny = (Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server' -Name fDenyTSConnections -ErrorAction SilentlyContinue).fDenyTSConnections
if ([int]$deny -eq 1) { Write-Output "PASS: RDP is disabled (fDenyTSConnections=1); NLA is not applicable."; return }
$nla = (Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' -Name UserAuthentication -ErrorAction SilentlyContinue).UserAuthentication
if ([int]$nla -eq 1) { Write-Output "PASS: RDP is enabled and requires Network Level Authentication (observed UserAuthentication=1)." }
else { $shown = 'absent'; if ($null -ne $nla) { $shown = $nla }; Write-Output "FAIL: RDP is enabled without Network Level Authentication (observed UserAuthentication=$shown)." }
